e_posts_story_idx', 'site_post_media_poster_idx', 'site_post_tags_profile_idx', 'site_post_tags_event_idx', 'site_post_tags_venue_idx', 'site_post_tags_target_idx', 'site_post_likes_profile_idx', 'site_post_saves_profile_idx', 'site_comments_post_idx', 'site_comments_author_idx', 'site_comments_reply_idx', 'site_member_lists_member_idx', 'site_ai_caption_uses_user_idx', 'site_reviews_one_per_venue', 'site_reviews_one_per_event', 'site_reviews_venue_idx', 'site_reviews_event_idx', 'site_dm_one_direct', 'site_dm_one_per_booking', 'site_dm_members_profile_idx', 'site_dm_messages_conversation_idx', 'site_dm_messages_client_key_idx', 'site_notifications_recipient_idx', 'site_notifications_unread_idx', 'site_reports_one_per_reporter', 'site_reports_open_idx', 'site_reports_target_idx', 'site_reports_reporter_day_idx']::text[])) = 44
  union all select 11, 'the social-media bucket exists and is private', coalesce((select case when b.public then 'public' else 'private' end from storage.buckets b where b.id = 'social-media'), 'missing'), 'private', coalesce((select not b.public from storage.buckets b where b.id = 'social-media'), false)
  union all select 12, 'its 3 storage policies exist', (select count(*) from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and p.policyname = any(array['social media readable by those who may see the post', 'profiles add their own social media', 'profiles remove their own social media']::text[]))::text, '3', (select count(*) from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and p.policyname = any(array['social media readable by those who may see the post', 'profiles add their own social media', 'profiles remove their own social media']::text[])) = 3
  union all select 13, 'the new columns exist', (select count(*) from unnest(array['site_venues.amenities', 'site_venues.parking_info', 'site_venues.min_age', 'site_venues.id_required', 'site_venues.last_entry', 'site_venues.kitchen_hours', 'site_venues.menu_url']::text[]) x where exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = split_part(x, '.', 1) and c.column_name = split_part(x, '.', 2)))::text, '7', (select count(*) from unnest(array['site_venues.amenities', 'site_venues.parking_info', 'site_venues.min_age', 'site_venues.id_required', 'site_venues.last_entry', 'site_venues.kitchen_hours', 'site_venues.menu_url']::text[]) x where exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = split_part(x, '.', 1) and c.column_name = split_part(x, '.', 2))) = 7
  union all select 14, 'all 16 feature switches exist', (select count(*) from public.site_feature_flags)::text, '16', (select count(*) from public.site_feature_flags) = 16
  union all select 15, '...and every one is OFF (nothing changes in the apps until you switch one on)', (select count(*) from public.site_feature_flags where enabled)::text, '0', (select count(*) from public.site_feature_flags where enabled) = 0
  union all select 16, 'a visitor can ask which are on', (select count(*) from jsonb_object_keys(public.site_features()))::text, '16', (select count(*) from jsonb_object_keys(public.site_features())) = 16
  union all select 17, 'the community rules are at version 1 with no text yet (the app shows its own draft)', (public.rules_current())::text, '{"body": null, "version": 1}', (public.rules_current())::text = '{"body": null, "version": 1}'
  union all select 18, 'no foreign key from the new tables into a person refuses an account deletion', (select count(*) from pg_constraint c where c.contype = 'f' and c.confdeltype in ('a', 'r') and replace(c.conrelid::regclass::text, 'public.', '') = any(array['site_feature_flags', 'site_profiles', 'site_handles', 'site_follows', 'site_blocks', 'site_posts', 'site_post_media', 'site_post_tags', 'site_post_likes', 'site_post_saves', 'site_comments', 'site_member_lists', 'site_story_views', 'site_banned_terms', 'site_community_rules', 'site_ai_caption_uses', 'site_rules_acceptance', 'site_reviews', 'site_review_replies', 'site_dm_conversations', 'site_dm_members', 'site_dm_messages', 'site_notifications', 'site_notification_opt_outs', 'site_reports']::text[]) and c.confrelid in ('auth.users'::regclass, 'public.profiles'::regclass, 'public.site_profiles'::regclass))::text, '0', (select count(*) from pg_constraint c where c.contype = 'f' and c.confdeltype in ('a', 'r') and replace(c.conrelid::regclass::text, 'public.', '') = any(array['site_feature_flags', 'site_profiles', 'site_handles', 'site_follows', 'site_blocks', 'site_posts', 'site_post_media', 'site_post_tags', 'site_post_likes', 'site_post_saves', 'site_comments', 'site_member_lists', 'site_story_views', 'site_banned_terms', 'site_community_rules', 'site_ai_caption_uses', 'site_rules_acceptance', 'site_reviews', 'site_review_replies', 'site_dm_conversations', 'site_dm_members', 'site_dm_messages', 'site_notifications', 'site_notification_opt_outs', 'site_reports']::text[]) and c.confrelid in ('auth.users'::regclass, 'public.profiles'::regclass, 'public.site_profiles'::regclass)) = 0
) x order by n;
